// scripts/generate-redirects.ts
//
// Static export only prerenders the canonical surah URL (`17_Al-Isra'`), while
// the old server-rendered app accepted any `17_<anything>` (e.g. `17_Al-Isra`
// without the apostrophe). Emit a Cloudflare `_redirects` file that 301s the
// apostrophe-less spellings to the canonical URLs so those links keep working.
import { writeFile } from "fs/promises";
import path from "path";
import { surahsBahasa } from "../content/quran/metadata";

async function generateRedirects() {
  const lines: string[] = [
    "# Generated by scripts/generate-redirects.ts. Do not edit.",
  ];
  let count = 0;

  for (const surah of surahsBahasa) {
    const alias = surah.name.replace(/'/g, "").replace(/\s+/g, "-");
    if (alias === surah.name) continue;

    // Redirect targets must not contain spaces; percent-encode the canonical id.
    const canonical = `${surah.number}_${encodeURI(surah.name)}`;
    const from = `/quran/surah/${surah.number}_${alias}`;
    const to = `/quran/surah/${canonical}`;
    lines.push(`${from} ${to} 301`);
    lines.push(`${from}/ayat/:ayat ${to}/ayat/:ayat 301`);
    count += 2;
  }

  await writeFile(
    path.join(process.cwd(), "public", "_redirects"),
    lines.join("\n") + "\n"
  );
  console.log(`Generated ${count} Cloudflare redirects.`);
}

generateRedirects();
